import semver
p = semver.createparser()
# Get compare subparser args
subparsers_actions = [action for action in p._subparsers._actions if hasattr(action, 'choices')]
if subparsers_actions:
    choices = subparsers_actions[0].choices
    if 'compare' in choices:
        compare_parser = choices['compare']
        print("Compare parser arguments:")
        for action in compare_parser._actions:
            if hasattr(action, 'dest') and action.dest != 'help':
                print(f"  {action.dest}")
